import java.util.Collections;
import java.util.List;

import org.eclipse.rdf4j.http.server.ClientHTTPException;
import org.eclipse.rdf4j.http.server.repository.RepositoryInterceptor;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.manager.RepositoryManager;
import org.junit.jupiter.api.Test;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

class TransactionMaintenanceTest {
	@Test
	void transactionBetweenHttpRequestsBlocksLifecycleChange() throws Exception {
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		when(connection.getParserConfig()).thenReturn(new org.eclipse.rdf4j.rio.ParserConfig());
		when(repository.getConnection()).thenReturn(connection);
		RepositoryManager manager = mock(RepositoryManager.class);
		when(manager.getInitializedRepositories()).thenReturn(List.of(repository));
		when(manager.hasRepositoryConfig("source")).thenReturn(true);
		Transaction transaction = new Transaction(repository);
		ActiveTransactionRegistry.INSTANCE.register(transaction);
		try {
			RepositoryInterceptor interceptor = new RepositoryInterceptor();
			interceptor.setRepositoryManager(manager);
			HttpServletRequest request = mock(HttpServletRequest.class);
			when(request.getMethod()).thenReturn("PUT");
			when(request.getPathInfo()).thenReturn("/source/config");
			when(request.getParameterNames()).thenReturn(Collections.emptyEnumeration());
			assertThrows(ClientHTTPException.class,
					() -> interceptor.preHandle(request, mock(HttpServletResponse.class), null));
		} finally {
			ActiveTransactionRegistry.INSTANCE.deregister(transaction);
		}
	}
}
